sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiProperties = [
        'sam.implementation.custom.data.entities'
    ];

    var kpiValues = {
        'data_kpi': []
    };

    function fetchKPIs(propertyName) {
        var kpis = [];
        var propertyValue = gs.getProperty(propertyName);

        if (propertyValue) {
            try {
                gs.log("Raw property value: " + propertyValue);
                kpis = JSON.parse(propertyValue);
                gs.log("Parsed KPIs for " + propertyName + ": " + JSON.stringify(kpis));
            } catch (e) {
                gs.log("Error parsing " + propertyName + ": " + e.message);
            }
        } else {
            gs.log("Property " + propertyName + " is not set or is empty.");
        }
        return kpis;
    }

    function processKPI(kpis, kpiType) {
        if (Array.isArray(kpis)) {
            gs.log("Processing KPIs for " + kpiType + ": " + JSON.stringify(kpis));
            kpis.forEach(function(kpi, index) {
                if (kpi.table && kpi.query) {
                    var queryCount = getQueryCount(kpi.table, kpi.query);
                    var totalCount = getTotalCount(kpi.table);
                    var percentage = totalCount > 0 ? Math.round((queryCount / totalCount) * 100) : 0;

                    kpiValues[kpiType].push({
                        'kpi': kpi.content,
                        'usecase': kpi.usecase,
                        'table': kpi.table,
                        'query': queryCount,
                        'total': totalCount,
                        'percentage': percentage, // Rounded to 2 decimal places
                        'recommendation': kpi.recommendation
                    });

                    gs.log("Processed KPI: " + JSON.stringify(kpiValues[kpiType][kpiValues[kpiType].length - 1]));
                } else {
                    gs.log("Skipping KPI missing table or query: " + JSON.stringify(kpi));
                }
            });
        } else {
            gs.log("Invalid KPI format for " + kpiType + ": " + JSON.stringify(kpis));
        }
    }

    function getQueryCount(tableName, query) {
        try {
            var gr = new GlideAggregate(tableName);
            gr.addEncodedQuery(query);
            gr.addAggregate('COUNT');
            gr.query();

            if (gr.next()) {
                return parseInt(gr.getAggregate('COUNT'), 10);
            }
            return 0;
        } catch (error) {
            gs.log("Error querying table " + tableName + ": " + error.message);
            return 0;
        }
    }

    function getTotalCount(tableName) {
        try {
            var gr = new GlideAggregate(tableName);
            gr.addAggregate('COUNT');
            gr.query();

            if (gr.next()) {
                return parseInt(gr.getAggregate('COUNT'), 10);
            }
            return 0;
        } catch (error) {
            gs.log("Error querying total count for table " + tableName + ": " + error.message);
            return 0;
        }
    }

    kpiProperties.forEach(function(property, index) {
        var kpiType = Object.keys(kpiValues)[index];
        gs.log("Fetching KPIs for property: " + property + " as type: " + kpiType);
        var kpis = fetchKPIs(property);
        processKPI(kpis, kpiType);
    });

    return kpiValues;
}
